#!/usr/bin/env python3
from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[1]
APP = ROOT / "estrada-play-comunista-app"
JAVA = APP / "app/src/main/java/com/estradaplay/comunista"


def read(p): return p.read_text(encoding="utf-8")
def write(p, s): p.write_text(s, encoding="utf-8")
def replace_once(s, old, new, label):
    if new in s: return s
    if old not in s: raise SystemExit(f"Trecho não encontrado: {label}")
    return s.replace(old, new, 1)

# -----------------------------------------------------------------------------
# 1.6.0 UNIVERSAL — painel total, mantendo a estabilização 1.5.2/1.5.3.
# -----------------------------------------------------------------------------
gradle = APP / "app/build.gradle"
s = read(gradle)
s = re.sub(r"versionCode\s+153\b", "versionCode 160", s, count=1)
s = re.sub(r"versionName\s+'1\.5\.3'", "versionName '1.6.0'", s, count=1)
write(gradle, s)

# Settings --------------------------------------------------------------------
write(JAVA / "DriveSettings.java", r'''package com.estradaplay.comunista;
import android.content.Context;
import android.content.SharedPreferences;
import java.util.Calendar;
final class DriveSettings {
    private static final String P="epc_drive_settings_v160";
    static SharedPreferences p(Context c){return c.getSharedPreferences(P,Context.MODE_PRIVATE);}
    static boolean autoNight(Context c){return p(c).getBoolean("auto_night",true);}
    static boolean hudMirror(Context c){return p(c).getBoolean("hud_mirror",true);}
    static boolean collectiveEnabled(Context c){return p(c).getBoolean("collective_enabled",true);}
    static boolean protectImpactVideo(Context c){return p(c).getBoolean("protect_impact_video",true);}
    static boolean offlineTestMode(Context c){return p(c).getBoolean("offline_test_mode",false);}
    static boolean onlyRoadMode(Context c){return p(c).getBoolean("only_road_mode",false);}
    static boolean manualRain(Context c){return p(c).getBoolean("rain_manual",false);}
    static boolean autoRain(Context c){return p(c).getBoolean("rain_auto",true);}
    static boolean rainAutoDetected(Context c){long at=p(c).getLong("rain_auto_at",0);return p(c).getBoolean("rain_auto_detected",false)&&System.currentTimeMillis()-at<45L*60L*1000L;}
    static boolean rainNow(Context c){return manualRain(c)||(autoRain(c)&&rainAutoDetected(c));}
    static void setRainAutoDetected(Context c,boolean value){p(c).edit().putBoolean("rain_auto_detected",value).putLong("rain_auto_at",System.currentTimeMillis()).apply();}
    static boolean nightNow(Context c){if(!autoNight(c))return p(c).getBoolean("night_force",false);int h=Calendar.getInstance().get(Calendar.HOUR_OF_DAY);return h>=19||h<6;}
    static void toggle(Context c,String key,boolean value){p(c).edit().putBoolean(key,value).apply();}
    static float consumptionKml(Context c){return VehicleProfileStore.active(c).kmL;}
    static float fuelPrice(Context c){return VehicleProfileStore.active(c).fuelPrice;}
    static float tankLiters(Context c){return VehicleProfileStore.active(c).tankL;}
    static float fuelPercent(Context c){return VehicleProfileStore.active(c).fuelPercent;}
    static void setVehicleCost(Context c,float kmL,float price){VehicleProfileStore.Profile a=VehicleProfileStore.active(c);VehicleProfileStore.save(c,new VehicleProfileStore.Profile(a.id,a.name,a.type,Math.max(1f,kmL),Math.max(0f,price),a.tankL,a.fuelPercent));}
    static int impactSensitivity(Context c){return Math.max(0,Math.min(2,p(c).getInt("impact_sensitivity",1)));}
    static void setImpactSensitivity(Context c,int value){p(c).edit().putInt("impact_sensitivity",Math.max(0,Math.min(2,value))).apply();}
}
''')

# Vehicle profiles ------------------------------------------------------------
write(JAVA / "VehicleProfileStore.java", r'''package com.estradaplay.comunista;
import android.content.Context;import android.content.SharedPreferences;import org.json.*;import java.util.*;
final class VehicleProfileStore{
 static final String P="epc_vehicle_profiles_v160",K="profiles",A="active";
 static final class Profile{final String id,name,type;final float kmL,fuelPrice,tankL,fuelPercent;Profile(String i,String n,String t,float k,float p,float tank,float pct){id=i==null||i.isEmpty()?String.valueOf(System.currentTimeMillis()):i;name=n==null||n.trim().isEmpty()?"Meu veículo":n.trim();type=t==null||t.trim().isEmpty()?"Carro":t.trim();kmL=Math.max(1,k);fuelPrice=Math.max(0,p);tankL=Math.max(1,tank);fuelPercent=Math.max(0,Math.min(100,pct));}float autonomyKm(){return tankL*(fuelPercent/100f)*kmL;}JSONObject json(){JSONObject o=new JSONObject();try{o.put("id",id);o.put("name",name);o.put("type",type);o.put("kml",kmL);o.put("price",fuelPrice);o.put("tank",tankL);o.put("pct",fuelPercent);}catch(Throwable ignored){}return o;}static Profile from(JSONObject o){if(o==null)return null;return new Profile(o.optString("id"),o.optString("name","Meu veículo"),o.optString("type","Carro"),(float)o.optDouble("kml",10),(float)o.optDouble("price",0),(float)o.optDouble("tank",50),(float)o.optDouble("pct",50));}}
 static SharedPreferences p(Context c){return c.getSharedPreferences(P,Context.MODE_PRIVATE);}static ArrayList<Profile> list(Context c){ArrayList<Profile> out=new ArrayList<>();try{JSONArray a=new JSONArray(p(c).getString(K,"[]"));for(int i=0;i<a.length();i++){Profile x=Profile.from(a.optJSONObject(i));if(x!=null)out.add(x);}}catch(Throwable ignored){}if(out.isEmpty()){Profile d=new Profile("default","Meu veículo","Carro",10,0,50,50);out.add(d);saveAll(c,out);p(c).edit().putString(A,d.id).apply();}return out;}static Profile active(Context c){ArrayList<Profile> a=list(c);String id=p(c).getString(A,"");for(Profile x:a)if(x.id.equals(id))return x;return a.get(0);}static void setActive(Context c,String id){p(c).edit().putString(A,id==null?"":id).apply();}static void save(Context c,Profile x){ArrayList<Profile>a=list(c);boolean found=false;for(int i=0;i<a.size();i++)if(a.get(i).id.equals(x.id)){a.set(i,x);found=true;break;}if(!found)a.add(x);saveAll(c,a);setActive(c,x.id);}static void remove(Context c,String id){ArrayList<Profile>a=list(c);a.removeIf(x->x.id.equals(id));if(a.isEmpty())a.add(new Profile("default","Meu veículo","Carro",10,0,50,50));saveAll(c,a);setActive(c,a.get(0).id);}private static void saveAll(Context c,List<Profile>a){JSONArray j=new JSONArray();for(Profile x:a)j.put(x.json());p(c).edit().putString(K,j.toString()).apply();}}
''')

write(JAVA / "FuelingStore.java", r'''package com.estradaplay.comunista;
import android.content.Context;import android.content.SharedPreferences;import org.json.*;import java.util.*;
final class FuelingStore{private static final String P="epc_fueling_v160",K="rows";static void add(Context c,String vehicleId,double liters,double total,double odometer){try{JSONArray old=rows(c),out=new JSONArray();JSONObject o=new JSONObject();o.put("vehicle_id",vehicleId);o.put("at",System.currentTimeMillis());o.put("liters",Math.max(0,liters));o.put("total",Math.max(0,total));o.put("odometer",Math.max(0,odometer));out.put(o);for(int i=0;i<old.length()&&out.length()<60;i++)out.put(old.opt(i));c.getSharedPreferences(P,Context.MODE_PRIVATE).edit().putString(K,out.toString()).apply();}catch(Throwable ignored){}}static JSONArray rows(Context c){try{return new JSONArray(c.getSharedPreferences(P,Context.MODE_PRIVATE).getString(K,"[]"));}catch(Throwable e){return new JSONArray();}}static double actualKml(Context c,String vehicleId){JSONArray a=rows(c);JSONObject newest=null,previous=null;for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o==null||!vehicleId.equals(o.optString("vehicle_id"))||o.optDouble("odometer",0)<=0)continue;if(newest==null)newest=o;else{previous=o;break;}}if(newest==null||previous==null)return 0;double d=newest.optDouble("odometer")-previous.optDouble("odometer"),l=newest.optDouble("liters");return d>0&&l>0?d/l:0;}}
''')

