write(JAVA / "FavoriteRoadStore.java", r'''package com.estradaplay.comunista;
import android.content.Context;import org.json.*;import java.util.*;
final class FavoriteRoadStore{private static final String P="epc_road_favorites_v160",K="rows";static final class Item{final String name,type;final double lat,lon;Item(String n,String t,double a,double b){name=n==null?"Ponto":n;type=t==null?"":t;lat=a;lon=b;}}static void add(Context c,Item x){if(x==null)return;try{JSONArray old=raw(c),out=new JSONArray();JSONObject n=new JSONObject();n.put("name",x.name);n.put("type",x.type);n.put("lat",x.lat);n.put("lon",x.lon);out.put(n);for(int i=0;i<old.length()&&out.length()<50;i++){JSONObject o=old.optJSONObject(i);if(o==null)continue;if(Math.abs(o.optDouble("lat")-x.lat)<.00001&&Math.abs(o.optDouble("lon")-x.lon)<.00001)continue;out.put(o);}c.getSharedPreferences(P,Context.MODE_PRIVATE).edit().putString(K,out.toString()).apply();}catch(Throwable ignored){}}static ArrayList<Item> list(Context c){ArrayList<Item> out=new ArrayList<>();JSONArray a=raw(c);for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o!=null)out.add(new Item(o.optString("name"),o.optString("type"),o.optDouble("lat"),o.optDouble("lon")));}return out;}static void remove(Context c,double lat,double lon){JSONArray a=raw(c),out=new JSONArray();for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o==null)continue;if(Math.abs(o.optDouble("lat")-lat)<.00001&&Math.abs(o.optDouble("lon")-lon)<.00001)continue;out.put(o);}c.getSharedPreferences(P,Context.MODE_PRIVATE).edit().putString(K,out.toString()).apply();}private static JSONArray raw(Context c){try{return new JSONArray(c.getSharedPreferences(P,Context.MODE_PRIVATE).getString(K,"[]"));}catch(Throwable e){return new JSONArray();}}}
''')

write(JAVA / "RoadFavoritesActivity.java", r'''package com.estradaplay.comunista;
import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import androidx.activity.ComponentActivity;import java.util.*;
public final class RoadFavoritesActivity extends ComponentActivity{private LinearLayout page;private int TEXT=Color.rgb(246,238,224),MUTED=Color.rgb(174,151,146),RED=Color.rgb(190,18,38);@Override protected void onCreate(Bundle b){super.onCreate(b);build();}private void build(){ScrollView sv=new ScrollView(this);page=new LinearLayout(this);page.setOrientation(LinearLayout.VERTICAL);page.setPadding(dp(18),dp(18),dp(18),dp(28));page.setBackgroundColor(Color.rgb(9,5,7));sv.addView(page);setContentView(sv);page.addView(t("FAVORITOS DA ESTRADA",27,TEXT,true));page.addView(t("Postos, oficinas, hospitais e paradas salvos no aparelho.",12,MUTED,false));ArrayList<FavoriteRoadStore.Item>a=FavoriteRoadStore.list(this);if(a.isEmpty())page.addView(t("Nenhum favorito ainda. Salve pela tela Serviços na Estrada.",14,MUTED,false));for(FavoriteRoadStore.Item x:a){LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.HORIZONTAL);Button go=new Button(this);go.setAllCaps(false);go.setText(x.name+"\n"+x.type);go.setOnClickListener(v->{DestinationStore.save(this,new DestinationStore.Destination(x.name,x.lat,x.lon));startActivity(new Intent(this,RoadMapActivity.class));});Button del=new Button(this);del.setText("REMOVER");del.setOnClickListener(v->{FavoriteRoadStore.remove(this,x.lat,x.lon);build();});r.addView(go,new LinearLayout.LayoutParams(0,dp(66),1));r.addView(del,new LinearLayout.LayoutParams(dp(105),dp(66)));page.addView(r);} }private TextView t(String v,float s,int c,boolean b){TextView t=new TextView(this);t.setText(v);t.setTextSize(s);t.setTextColor(c);if(b)t.setTypeface(android.graphics.Typeface.DEFAULT,android.graphics.Typeface.BOLD);return t;}private int dp(float v){return Math.round(v*getResources().getDisplayMetrics().density);}}
''')

# Road quality ----------------------------------------------------------------
write(JAVA / "RoadQualityStore.java", r'''package com.estradaplay.comunista;
import android.content.Context;import org.json.*;import java.util.*;
final class RoadQualityStore{private static final String P="epc_road_quality_v160",K="cells";static final class Point{final double lat,lon;final int score,count;Point(double a,double b,int s,int c){lat=a;lon=b;score=s;count=c;}}private final Context app;RoadQualityStore(Context c){app=c.getApplicationContext();}synchronized void record(RoadSurfaceMonitor.Impact x){if(x==null)return;try{JSONArray a=raw(),out=new JSONArray();String key=key(x.lat,x.lon);JSONObject hit=null;for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o!=null&&key.equals(o.optString("key"))){hit=o;break;}}if(hit==null){hit=new JSONObject();hit.put("key",key);hit.put("lat",x.lat);hit.put("lon",x.lon);hit.put("count",0);hit.put("force_sum",0);}hit.put("count",hit.optInt("count")+1);hit.put("force_sum",hit.optDouble("force_sum")+Math.max(0,x.force));hit.put("at",System.currentTimeMillis());out.put(hit);for(int i=0;i<a.length()&&out.length()<400;i++){JSONObject o=a.optJSONObject(i);if(o==null||key.equals(o.optString("key")))continue;out.put(o);}app.getSharedPreferences(P,Context.MODE_PRIVATE).edit().putString(K,out.toString()).apply();}catch(Throwable ignored){}}synchronized ArrayList<Point> around(double lat,double lon,double meters){ArrayList<Point> out=new ArrayList<>();JSONArray a=raw();for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o==null)continue;double la=o.optDouble("lat"),lo=o.optDouble("lon");if(RoadPackStore.distanceM(lat,lon,la,lo)>meters)continue;int count=Math.max(1,o.optInt("count",1));double avg=o.optDouble("force_sum")/count;int score=(int)Math.max(10,Math.min(95,100-count*6-avg*4));out.add(new Point(la,lo,score,count));}return out;}synchronized int scoreNear(double lat,double lon){ArrayList<Point>a=around(lat,lon,2500);if(a.isEmpty())return 100;double s=0,w=0;for(Point p:a){double ww=Math.max(1,p.count);s+=p.score*ww;w+=ww;}return (int)Math.round(s/w);}private JSONArray raw(){try{return new JSONArray(app.getSharedPreferences(P,Context.MODE_PRIVATE).getString(K,"[]"));}catch(Throwable e){return new JSONArray();}}private String key(double a,double b){return String.format(java.util.Locale.US,"%.3f:%.3f",a,b);}}
''')

# Online weather is optional. Failure never affects protection. ----------------
write(JAVA / "RoadWeatherMonitor.java", r'''package com.estradaplay.comunista;
import android.content.Context;import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.Locale;
final class RoadWeatherMonitor{private RoadWeatherMonitor(){}static void refresh(Context c,double lat,double lon){if(c==null||DriveSettings.offlineTestMode(c)||!DriveSettings.autoRain(c))return;HttpURLConnection h=null;try{String u=String.format(Locale.US,"https://api.open-meteo.com/v1/forecast?latitude=%.5f&longitude=%.5f&current=precipitation,rain,showers,weather_code",lat,lon);h=(HttpURLConnection)new URL(u).openConnection();h.setConnectTimeout(7000);h.setReadTimeout(9000);h.setRequestProperty("Accept","application/json");if(h.getResponseCode()<200||h.getResponseCode()>=300)return;ByteArrayOutputStream b=new ByteArrayOutputStream();try(InputStream in=h.getInputStream()){byte[]buf=new byte[8192];int n;while((n=in.read(buf))>0&&b.size()<300000)b.write(buf,0,n);}JSONObject root=new JSONObject(new String(b.toByteArray(),StandardCharsets.UTF_8));JSONObject cur=root.optJSONObject("current");if(cur==null)return;double p=cur.optDouble("precipitation",0)+cur.optDouble("rain",0)+cur.optDouble("showers",0);int code=cur.optInt("weather_code",0);boolean wet=p>0.05||(code>=51&&code<=82)||(code>=95);DriveSettings.setRainAutoDetected(c,wet);}catch(Throwable ignored){}finally{if(h!=null)h.disconnect();}}}
''')

# Trip recorder with sampled route --------------------------------------------
write(JAVA / "TripRecorder.java", r'''package com.estradaplay.comunista;
import android.content.*;import android.location.Location;import org.json.*;
final class TripRecorder{private static final String PREFS="epc_trip_history_v140",KEY_HISTORY="history",KEY_ACTIVE="active";private static final long IDLE_FINISH_MS=5L*60L*1000L;private final Context app;private final SharedPreferences prefs;private JSONObject active;private Location last,lastPath;private long lastMovingAt,lastPersistAt,lastPathAt;TripRecorder(Context c){app=c.getApplicationContext();prefs=app.getSharedPreferences(PREFS,Context.MODE_PRIVATE);try{String raw=prefs.getString(KEY_ACTIVE,"");if(raw!=null&&!raw.isEmpty())active=new JSONObject(raw);}catch(Throwable ignored){active=null;}}
 synchronized void onLocation(Location loc,double speedKmh){if(loc==null)return;long now=System.currentTimeMillis();if(speedKmh>=4){if(active==null)start(now,loc);lastMovingAt=now;}else if(active!=null&&lastMovingAt>0&&now-lastMovingAt>=IDLE_FINISH_MS){finish("parada");last=new Location(loc);return;}if(active==null){last=new Location(loc);return;}try{double add=0;if(last!=null){float d=last.distanceTo(loc);if(d>=0&&d<=1500)add=d;}active.put("distance_m",active.optDouble("distance_m",0)+add);active.put("max_speed",Math.max(active.optDouble("max_speed",0),Math.max(0,speedKmh)));active.put("last_lat",loc.getLatitude());active.put("last_lon",loc.getLongitude());active.put("updated_at",now);if(lastPath==null||now-lastPathAt>=30000L||lastPath.distanceTo(loc)>=300f)addPath(loc,speedKmh,now);if(now-lastPersistAt>=12000)persistActive();}catch(Throwable ignored){}last=new Location(loc);}
 synchronized void onHazard(String type){if(active==null)return;try{if("RADAR".equals(type))active.put("radars",active.optInt("radars",0)+1);else if("QUEBRA_MOLAS".equals(type))active.put("bumps",active.optInt("bumps",0)+1);else if("CAMERA_MONITORAMENTO".equals(type))active.put("cameras",active.optInt("cameras",0)+1);else active.put("other_alerts",active.optInt("other_alerts",0)+1);addTimeline(type,type,System.currentTimeMillis(),active.optDouble("last_lat",0),active.optDouble("last_lon",0),0);persistActive();}catch(Throwable ignored){}}
 synchronized void onRoadImpact(RoadSurfaceMonitor.Impact x){if(active==null||x==null)return;try{active.put("road_impacts",active.optInt("road_impacts",0)+1);active.put("roughness_sum",active.optDouble("roughness_sum",0)+x.force);addTimeline("VIA_IRREGULAR","Impacto/irregularidade",x.at,x.lat,x.lon,x.force);persistActive();}catch(Throwable ignored){}}
 synchronized void onRestSuggested(){if(active==null)return;try{addTimeline("PAUSA","Pausa sugerida",System.currentTimeMillis(),active.optDouble("last_lat",0),active.optDouble("last_lon",0),0);persistActive();}catch(Throwable ignored){}}
 synchronized void addManualEvent(String label,double lat,double lon,double speed){if(active==null)return;try{addTimeline("SALVO",label==null?"Acontecimento salvo":label,System.currentTimeMillis(),lat,lon,speed);persistActive();}catch(Throwable ignored){}}
 synchronized void finish(String reason){if(active==null)return;try{long now=System.currentTimeMillis();active.put("ended_at",now);active.put("duration_ms",Math.max(0,now-active.optLong("started_at",now)));active.put("reason",reason==null?"":reason);double km=active.optDouble("distance_m",0)/1000.0;double liters=km/DriveSettings.consumptionKml(app);active.put("fuel_l",liters);active.put("fuel_cost",liters*DriveSettings.fuelPrice(app));int impacts=active.optInt("road_impacts",0);double score=Math.max(1,Math.min(100,100-(impacts*120.0/Math.max(5.0,km))));active.put("road_quality_score",Math.round(score));JSONArray old=history(prefs),out=new JSONArray();out.put(active);for(int i=0;i<old.length()&&out.length()<30;i++)out.put(old.opt(i));prefs.edit().putString(KEY_HISTORY,out.toString()).remove(KEY_ACTIVE).apply();}catch(Throwable ignored){}active=null;last=null;lastPath=null;lastMovingAt=0;}
 private void start(long now,Location loc){active=new JSONObject();try{active.put("started_at",now);active.put("updated_at",now);active.put("start_lat",loc.getLatitude());active.put("start_lon",loc.getLongitude());active.put("distance_m",0);active.put("max_speed",0);active.put("radars",0);active.put("bumps",0);active.put("cameras",0);active.put("other_alerts",0);active.put("road_impacts",0);active.put("timeline",new JSONArray());active.put("path",new JSONArray());addTimeline("SAIDA","Viagem iniciada",now,loc.getLatitude(),loc.getLongitude(),0);addPath(loc,0,now);}catch(Throwable ignored){}lastMovingAt=now;persistActive();}
 private void addPath(Location l,double speed,long at){try{JSONArray a=active.optJSONArray("path");if(a==null)a=new JSONArray();JSONObject p=new JSONObject();p.put("lat",l.getLatitude());p.put("lon",l.getLongitude());p.put("speed",Math.max(0,speed));p.put("at",at);JSONArray out=new JSONArray();int start=Math.max(0,a.length()-239);for(int i=start;i<a.length();i++)out.put(a.opt(i));out.put(p);active.put("path",out);lastPath=new Location(l);lastPathAt=at;}catch(Throwable ignored){}}
 private void addTimeline(String type,String label,long at,double lat,double lon,double value){try{JSONArray a=active.optJSONArray("timeline");if(a==null)a=new JSONArray();JSONObject e=new JSONObject();e.put("type",type);e.put("label",label);e.put("at",at);e.put("lat",lat);e.put("lon",lon);if(value>0)e.put("value",value);JSONArray out=new JSONArray();int start=Math.max(0,a.length()-58);for(int i=start;i<a.length();i++)out.put(a.opt(i));out.put(e);active.put("timeline",out);}catch(Throwable ignored){}}
 private void persistActive(){lastPersistAt=System.currentTimeMillis();if(active!=null)prefs.edit().putString(KEY_ACTIVE,active.toString()).apply();}static JSONObject activeSnapshot(Context c){try{return new JSONObject(c.getSharedPreferences(PREFS,Context.MODE_PRIVATE).getString(KEY_ACTIVE,"{}"));}catch(Throwable e){return new JSONObject();}}static JSONArray history(Context c){return history(c.getSharedPreferences(PREFS,Context.MODE_PRIVATE));}private static JSONArray history(SharedPreferences p){try{return new JSONArray(p.getString(KEY_HISTORY,"[]"));}catch(Throwable ignored){return new JSONArray();}}static JSONObject trip(Context c,int index){JSONArray a=history(c);return index>=0&&index<a.length()?a.optJSONObject(index):null;}static void clear(Context c){c.getSharedPreferences(PREFS,Context.MODE_PRIVATE).edit().remove(KEY_HISTORY).apply();}}
''')

# Replay view/activity ---------------------------------------------------------
write(JAVA / "TripReplayActivity.java", r'''package com.estradaplay.comunista;
import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import androidx.activity.ComponentActivity;import org.json.*;import java.text.*;import java.util.*;
public final class TripReplayActivity extends ComponentActivity{private final int BG=Color.rgb(9,5,7),TEXT=Color.rgb(246,238,224),MUTED=Color.rgb(174,151,146),RED=Color.rgb(190,18,38);@Override protected void onCreate(Bundle b){super.onCreate(b);int idx=getIntent().getIntExtra("trip_index",0);JSONObject trip=TripRecorder.trip(this,idx);LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);p.setPadding(dp(16),dp(16),dp(16),dp(20));p.setBackgroundColor(BG);setContentView(p);p.addView(t("REPLAY DA VIAGEM",25,TEXT,true));if(trip==null){p.addView(t("Viagem não encontrada.",14,MUTED,false));return;}p.addView(new ReplayView(trip),new LinearLayout.LayoutParams(-1,0,1));p.addView(t(summary(trip),12,MUTED,false));}private String summary(JSONObject o){double km=o.optDouble("distance_m")/1000.0;return String.format(Locale.getDefault(),"%.1f km · máxima %.0f km/h · qualidade %d/100 · radares %d · impactos %d",km,o.optDouble("max_speed"),o.optInt("road_quality_score",100),o.optInt("radars"),o.optInt("road_impacts"));}private TextView t(String v,float s,int c,boolean b){TextView t=new TextView(this);t.setText(v);t.setTextSize(s);t.setTextColor(c);if(b)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}private int dp(float v){return Math.round(v*getResources().getDisplayMetrics().density);}private final class ReplayView extends View{private final JSONArray path,events;private final Paint line=new Paint(1),event=new Paint(1),start=new Paint(1),grid=new Paint(1);private double minLat=90,maxLat=-90,minLon=180,maxLon=-180;ReplayView(JSONObject o){super(TripReplayActivity.this);path=o.optJSONArray("path");events=o.optJSONArray("timeline");line.setColor(Color.rgb(224,30,47));line.setStyle(Paint.Style.STROKE);line.setStrokeWidth(dp(4));event.setColor(Color.rgb(226,185,76));start.setColor(Color.rgb(72,212,134));grid.setColor(Color.rgb(60,35,40));grid.setStyle(Paint.Style.STROKE);scan();}private void scan(){if(path==null)return;for(int i=0;i<path.length();i++){JSONObject p=path.optJSONObject(i);if(p==null)continue;double a=p.optDouble("lat",Double.NaN),b=p.optDouble("lon",Double.NaN);if(!Double.isFinite(a)||!Double.isFinite(b))continue;minLat=Math.min(minLat,a);maxLat=Math.max(maxLat,a);minLon=Math.min(minLon,b);maxLon=Math.max(maxLon,b);}}private float x(double lon){double d=Math.max(.0001,maxLon-minLon);return dp(18)+(float)((lon-minLon)/d)*(getWidth()-dp(36));}private float y(double lat){double d=Math.max(.0001,maxLat-minLat);return dp(18)+(float)((maxLat-lat)/d)*(getHeight()-dp(36));}@Override protected void onDraw(Canvas c){super.onDraw(c);c.drawColor(Color.rgb(14,8,11));for(int i=1;i<5;i++){float xx=getWidth()*i/5f,yy=getHeight()*i/5f;c.drawLine(xx,0,xx,getHeight(),grid);c.drawLine(0,yy,getWidth(),yy,grid);}if(path==null||path.length()<1)return;Path q=new Path();boolean first=true;for(int i=0;i<path.length();i++){JSONObject p=path.optJSONObject(i);if(p==null)continue;float xx=x(p.optDouble("lon")),yy=y(p.optDouble("lat"));if(first){q.moveTo(xx,yy);c.drawCircle(xx,yy,dp(7),start);first=false;}else q.lineTo(xx,yy);}c.drawPath(q,line);if(events!=null)for(int i=0;i<events.length();i++){JSONObject e=events.optJSONObject(i);if(e==null)continue;double a=e.optDouble("lat",Double.NaN),b=e.optDouble("lon",Double.NaN);if(Double.isFinite(a)&&Double.isFinite(b))c.drawCircle(x(b),y(a),dp(4),event);}}}}
''')

