write(JAVA / "TripPlannerActivity.java", r'''package com.estradaplay.comunista;
import android.Manifest;import android.content.*;import android.content.pm.PackageManager;import android.graphics.*;import android.location.*;import android.os.*;import android.view.*;import android.widget.*;import androidx.activity.ComponentActivity;import org.json.*;import java.util.*;import java.util.concurrent.*;
public final class TripPlannerActivity extends ComponentActivity{private final int BG=Color.rgb(9,5,7),TEXT=Color.rgb(246,238,224),MUTED=Color.rgb(174,151,146),RED=Color.rgb(190,18,38),GREEN=Color.rgb(72,212,134);private LinearLayout page;private final ExecutorService io=Executors.newSingleThreadExecutor();@Override protected void onCreate(Bundle b){super.onCreate(b);build();}@Override protected void onDestroy(){io.shutdownNow();super.onDestroy();}private void build(){ScrollView sv=new ScrollView(this);page=new LinearLayout(this);page.setOrientation(LinearLayout.VERTICAL);page.setPadding(dp(18),dp(18),dp(18),dp(28));page.setBackgroundColor(BG);sv.addView(page);setContentView(sv);DestinationStore.Destination d=DestinationStore.read(this);page.addView(t("PLANEJADOR DE VIAGEM",27,TEXT,true));page.addView(t(d==null?"Defina um destino para calcular distância, tempo, combustível e perigos.":"Destino · "+d.label,13,MUTED,false));Button dest=b(d==null?"DEFINIR DESTINO":"MUDAR DESTINO",false);page.addView(dest,new LinearLayout.LayoutParams(-1,dp(52)));dest.setOnClickListener(v->startActivity(new Intent(this,DestinationActivity.class)));Button road=b("INICIAR MODO SÓ ESTRADA",false);page.addView(road,new LinearLayout.LayoutParams(-1,dp(52)));road.setOnClickListener(v->{DriveSettings.toggle(this,"only_road_mode",true);DestinationStore.clear(this);startActivity(new Intent(this,RoadMapActivity.class));});if(d==null)return;Button calc=b("CALCULAR PLANO",true);page.addView(calc,new LinearLayout.LayoutParams(-1,dp(58)));calc.setOnClickListener(v->calculate(d));}private void calculate(DestinationStore.Destination d){if(DriveSettings.offlineTestMode(this)){toast("O cálculo de rota é online. Encerre o teste offline; os alertas continuam offline.");return;}Location l=last();if(l==null){toast("Ainda não tenho posição GPS.");return;}page.addView(t("CALCULANDO…",14,RED,true));io.execute(()->{try{RouteEngine.Route r=RouteEngine.fetch(l.getLatitude(),l.getLongitude(),d.lat,d.lon);RoadPackStore store=new RoadPackStore(getApplicationContext());RoadQualityStore quality=new RoadQualityStore(getApplicationContext());Plan p=analyze(r,store,quality);runOnUiThread(()->showPlan(r,p,d));}catch(Throwable e){runOnUiThread(()->toast("Não consegui calcular a rota agora."));}});}private Plan analyze(RouteEngine.Route r,RoadPackStore store,RoadQualityStore quality){Plan p=new Plan();try{JSONObject root=new JSONObject(r.geoJson);JSONArray f=root.optJSONArray("features");JSONObject g=f==null?null:f.optJSONObject(0);JSONObject geo=g==null?null:g.optJSONObject("geometry");JSONArray coords=geo==null?null:geo.optJSONArray("coordinates");HashSet<String> ids=new HashSet<>();double score=0;int scoreN=0;if(coords!=null){int step=Math.max(1,coords.length()/55);for(int i=0;i<coords.length();i+=step){JSONArray c=coords.optJSONArray(i);if(c==null)continue;double lon=c.optDouble(0),lat=c.optDouble(1);for(RoadHazard h:store.nearby(lat,lon,500)){if(!ids.add(h.id))continue;if("RADAR".equals(h.type))p.radars++;else if("QUEBRA_MOLAS".equals(h.type))p.bumps++;else if("PEDAGIO".equals(h.type))p.tolls++;}score+=quality.scoreNear(lat,lon);scoreN++;}}p.quality=scoreN==0?100:(int)Math.round(score/scoreN);}catch(Throwable ignored){}return p;}private void showPlan(RouteEngine.Route r,Plan p,DestinationStore.Destination d){VehicleProfileStore.Profile v=VehicleProfileStore.active(this);double km=r.distanceM/1000.0,liters=km/v.kmL,cost=liters*v.fuelPrice;page.addView(t("PLANO PRONTO",16,GREEN,true));page.addView(t(r.summary()+"\nCombustível: "+String.format(Locale.getDefault(),"%.1f L",liters)+(v.fuelPrice>0?String.format(Locale.getDefault()," · R$ %.2f",cost):" · preço não informado")+"\nRadares na faixa da rota: "+p.radars+" · Quebra-molas: "+p.bumps+" · Pedágios detectados: "+p.tolls+"\nPreço dos pedágios: indisponível sem fonte confiável\nQualidade local estimada: "+p.quality+"/100",15,TEXT,true));Button go=b("INICIAR VIAGEM",true);page.addView(go,new LinearLayout.LayoutParams(-1,dp(58)));go.setOnClickListener(x->{DriveSettings.toggle(this,"only_road_mode",false);startActivity(new Intent(this,RoadMapActivity.class));});}private Location last(){if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED&&checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)!=PackageManager.PERMISSION_GRANTED)return null;try{LocationManager m=(LocationManager)getSystemService(LOCATION_SERVICE);Location best=null;for(String p:new String[]{LocationManager.GPS_PROVIDER,LocationManager.NETWORK_PROVIDER}){Location x=m.getLastKnownLocation(p);if(x!=null&&(best==null||x.getTime()>best.getTime()))best=x;}return best;}catch(Throwable e){return null;}}private Button b(String s,boolean pri){Button b=new Button(this);b.setText(s);b.setTextColor(TEXT);if(pri)b.setBackgroundColor(RED);return b;}private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}private TextView t(String v,float s,int c,boolean b){TextView t=new TextView(this);t.setText(v);t.setTextSize(s);t.setTextColor(c);if(b)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}private int dp(float v){return Math.round(v*getResources().getDisplayMetrics().density);}private static final class Plan{int radars,bumps,tolls,quality=100;}}
''')

